INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G89XGF4AFJXVDXNH6X8C7B5G', 'story', '06FB0TNQM5TWC00GW0P3X02HZW', 'clide clipboard set/history CLI verbs', 'The clipboard is UI-only: kernel ClideClipboard exists with writePlain/readPlain/history and OS sync, but no dispatcher verb exposes it, so D-6 parity is broken. Add clipboard.set (with a toast, since overwriting a paste buffer must not be silent) and clipboard.history. No read verb by design — the user''s clipboard holds secrets.', 'backlog', 'high', NULL, NULL, 'D-6', '2026-09-09 06:58:33.378', '2026-09-09 06:58:33.378', NULL, 'd9a186c510219e0092bb7966ee1edbf2', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G89XGF4AFJXVDXNH6X8C7B5G', 'story', '06FB0TNQM5TWC00GW0P3X02HZW', 'clide clipboard set/history CLI verbs', 'The clipboard is UI-only: kernel ClideClipboard exists with writePlain/readPlain/history and OS sync, but no dispatcher verb exposes it, so D-6 parity is broken. Add clipboard.set (with a toast, since overwriting a paste buffer must not be silent) and clipboard.history. No read verb by design — the user''s clipboard holds secrets.', 'done', 'high', NULL, NULL, 'D-6', '2026-09-09 06:58:33.378', '2026-09-09 07:09:25.461', NULL, '9de9cc66608dbf9d396ac83158edbedd', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06G8AA5V21410GE02SR26EPD6W', 'bug', '06FB0TNQM5TWC00GW0P3X02HZW', 'Injected agent note duplicated a stale subsystem list', 'clideContextNote hardcoded ''subsystems that respond today: files, editor, git, search, pql, panel/pane'' while 16 dispatched, so a hosted session read the other nine (clipboard, ui, image, icon, canvas, project, env, log, claude) as not existing. A second copy of the command registry that nothing forces anyone to update, failing silently toward hiding features. Replace with a pointer to clide capabilities, which is generated from the live registry.', 'backlog', 'high', NULL, NULL, 'D-6', '2026-09-09 07:53:54.192', '2026-09-09 07:53:54.192', NULL, 'e6c98323e7b951de734ea30a2bf4b59d', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
