INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCT8JAS881CFAHYWGRE4Y1WR', 'task', '06FB0TNQM5TWC00GW0P3X02HZW', 'Context panel max width scales with the window on widescreens', NULL, 'backlog', 'medium', NULL, NULL, 'D-47', '2026-09-23 07:19:31.786', '2026-09-23 07:19:31.786', NULL, '267e08c49ec7b3275606238a3547a0e6', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCT8JAS881CFAHYWGRE4Y1WR', 'task', '06FB0TNQM5TWC00GW0P3X02HZW', 'Context panel max width scales with the window on widescreens', 'The context panel''s maximum width is a fixed 1000 logical px (`maxSize: 1000` for `Slots.contextPanel` in `lib/kernel/src/panels/layout_preset.dart:19`, clamped in `LayoutArrangement.setSize`). On a widescreen (user''s window: 3435px wide) the panel stops at ~29% of the window while the Claude pane gets the rest. Reading a ticket or decision there leaves a lot of screen unused.

User 2026-09-23: "make the maximum width of the context panel more responsive to widescreens: it could be a bit wider if I have this much screen."

Want: the max width scales with the window, e.g. `max(1000, fraction × window width)`. The fraction should still leave the Claude pane a sensible minimum (D-47: Claude stays the largest surface). The same probably applies to the sidebar''s fixed 400 max.

Notes:
- The max is currently static preset data (`LayoutSlot.maxSize`), so a window-relative limit needs either a resolver the arrangement consults at clamp time, or a max the shell recomputes when the window resizes. Pick one and apply it to both side slots.
- A persisted size saved while the window was wide must still clamp correctly on a narrow window (and vice versa).
- `clide panel resize --to` goes through the same clamp; its error/clamp messages should report the effective max.

Acceptance: on a wide window the context panel can be dragged well past 1000px (up to the fraction); on a ~1600px window behaviour is unchanged; Claude never drops below its minimum; covered by arrangement tests at two window widths.', 'backlog', 'medium', NULL, NULL, 'D-47', '2026-09-23 07:19:31.786', '2026-09-23 07:19:41.110', NULL, '43328395fc348a4994158b3666796582', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCT929BB9PM3C1NVM0FDNRJC', 'task', '06FB0TNQM5TWC00GW0P3X02HZW', 'Ticket detail view: show child tickets (epics/stories hide their contents today)', NULL, 'backlog', 'medium', NULL, NULL, 'D-3', '2026-09-23 07:21:42.490', '2026-09-23 07:21:42.490', NULL, '22a227ed275eaabab4df0f68c664abff', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCT929BB9PM3C1NVM0FDNRJC', 'task', '06FB0TNQM5TWC00GW0P3X02HZW', 'Ticket detail view: show child tickets (epics/stories hide their contents today)', 'The ticket detail view (context panel) shows a ticket''s PARENT TREE but never its children. Opening an epic or story therefore hides what it contains. The user''s screenshot of T-276 (the UI tracker epic, which has dozens of children) showed only its own description.

User 2026-09-23: "a ticket to add child tickets. in the previous screenshot the 276 ticket has a lot of children, but they are not shown".

Today: `TicketDetailController.load` requests `pql.tickets.show` with `withContext: true` and reads only `ancestors` + `decisions`; `TicketDetail` has no children field; `ticket_detail_view.dart` renders a parents section (`_CompactCard` rows) and nothing below.

Want: a CHILDREN section under the description, listing the direct children as the same compact cards (id, type colour, title, status), each opening that ticket in the reader on click (via the same ReaderNav `selection` path, so back/forward works). Order: open work first (in_progress, then ready/backlog), done last. An epic like T-276 can have many, so collapse done children behind a "N done" toggle, or cap with "show all".

Data: pql already supports `pql ticket show <id> --with-children` (returns a `children` array: id/type/title/status/priority). Check whether the clide `pql.tickets.show` wrapper (lib/src/pql/) passes it through with `withContext`, or add a `withChildren` arg. Wrap, don''t duplicate (D-3).

Acceptance: opening T-276 lists its children; clicking one navigates to it and Back returns; a leaf ticket shows no children section; done children are de-emphasised or collapsed; covered by controller + widget tests.', 'backlog', 'medium', NULL, NULL, 'D-3', '2026-09-23 07:21:42.490', '2026-09-23 07:21:44.503', NULL, '307705a4aa35031fbf8bfc2cbbe639fe', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCT0JARSZBYE6WJ9A7S5G0JW', 'task', '06FB0TNQM66FTCTWHH9AQTNFKR', 'Tray: Linux loader (--loader) — single-instance, StatusNotifierItem + DBusMenu over GDBus, window registry; window bridge + close-to-tray', NULL, 'done', 'medium', NULL, NULL, 'D-110', '2026-09-23 06:44:34.630', '2026-09-23 07:22:11.874', NULL, 'ad806f4b277dc8407aee44e49a5e6282', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06FB0TNQM66FTCTWHH9AQTNFKR', 'story', NULL, 'system tray and dock persistence', 'Minimize to system tray on Linux (AppIndicator) or Dock on macOS. Reopening from tray restores the window without cold boot. tmux sessions stay alive in background regardless.

Scope split (2026-06-10 sweep): the session-persistence half is effectively done - tmux keeps Claude/terminal sessions alive across restart (D-41). The OS-tray/AppIndicator + dock half is a stub only (lib/kernel/src/tray.dart - TrayRegistry has no platform-channel wiring) and is Tier-6+. Remaining work = the tray integration.

CORRECTION 2026-09-23: the ''session-persistence half is done (tmux)'' premise is stale — nothing in clide uses tmux since D-77. Quitting clide kills every claude child and terminal PTY; only conversations survive (--resume). So the tray/dock is now what keeps sessions alive while the window is closed. Decided with user: Linux tray = own StatusNotifierItem + minimal DBusMenu over GDBus (no new dep); close hides to tray behind an opt-out setting, quits when no tray host exists; tray right-click must offer Quit all (all clide windows); platforms Linux + macOS (Dock) + Windows (notification area), macOS/Windows as plumbing to be tested on those machines; ONE shared tray icon across all clide processes (each window is its own process). Open: which process owns the icon — elected among windows vs a thin loader process that also serves T-47.

STATUS 2026-09-23: Linux done and verified live on KDE Plasma 6/Wayland (T-591); Dart half + General settings tab (T-590); notification pulse spins the tray icon. macOS Dock (T-592) and Windows notification-area loader (T-593) are committed as plumbing, untested — in review, to be built and exercised on a Mac and a Windows machine. Close T-55 once both are confirmed.', 'in_progress', 'medium', NULL, NULL, NULL, '2026-04-23 20:32:06', '2026-09-23 07:22:13.954', NULL, '8aae74f6f48d9f9dbe32cb378acc35ca', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
INSERT INTO tickets (record_id, type, parent_record_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('06GCT0JDZA1E8ACCF0W7H6Y198', 'task', '06FB0TNQM66FTCTWHH9AQTNFKR', 'Tray: macOS Dock — keep alive on close, reopen on Dock click, Dock menu Quit all (plumbing, untested)', NULL, 'review', 'medium', NULL, NULL, 'D-110', '2026-09-23 06:44:35.450', '2026-09-23 07:22:15.974', NULL, '9660b16517f7acfccc51a2331aacf416', 2) ON CONFLICT(record_id) DO UPDATE SET type=excluded.type, parent_record_id=excluded.parent_record_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at >= tickets.updated_at;
